// design-fonts.js
//
// Real typefaces for the built-in designer, embedded straight into every SVG design. Nothing is hosted or fetched:
// a design is shown as an <img> (an SVG used as an image cannot load outside files), so the fonts have to travel
// inside the SVG itself, and that is what fontFaceStyle() does. It adds a small @font-face block with only the
// faces a given design actually uses (about 15 KB each, 40-60 KB for a typical design).
//
// Faces (all SIL Open Font License 1.1, free to embed and redistribute):
//   CgSans   Inter 400 / 600 / 800            (c) The Inter Project Authors, https://github.com/rsms/inter
//   CgHead   Inter Display Black 900          same family, display cut, used for loud poster headlines
//   CgRound  Poppins Bold 700                 (c) The Poppins Project Authors, https://github.com/itfoundry/poppins
//   CgSerif  Lora Bold 700 + Lora Italic 400  (c) The Lora Project Authors, https://github.com/cyrealtype/Lora-Cyrillic
// Each file was cut down to Basic Latin, Latin-1, curly quotes, dashes, the bullet, the euro and the NAIRA sign, with
// kerning kept, hinting removed and WOFF compression. Poppins and Lora have no naira sign, so designs that contain
// one also embed Inter as the fallback (see FALLBACK).
//
// This file is generated data. Do not edit by hand.

const FACES = {
  sans400: { family: 'CgSans', weight: 400, style: 'normal', b64: '' },
  sans600: { family: 'CgSans', weight: 600, style: 'normal', b64: '' },
  sans800: { family: 'CgSans', weight: 800, style: 'normal', b64: '' },
  head900: { family: 'CgHead', weight: 900, style: 'normal', b64: '' },
  round700: { family: 'CgRound', weight: 700, style: 'normal', b64: '' },
  serif700: { family: 'CgSerif', weight: 700, style: 'normal', b64: '' },
  serifI400: { family: 'CgSerif', weight: 400, style: 'italic', b64: '' },
};

const FAMILY_FACES = {};
for (const k of Object.keys(FACES)) (FAMILY_FACES[FACES[k].family] = FAMILY_FACES[FACES[k].family] || []).push(k);

// Families that lack the naira sign, and the family that supplies it instead.
const FALLBACK = { CgRound: 'CgHead', CgSerif: 'CgSans' };

const _cache = new Map();

function _css(keys) {
  const id = keys.join('|');
  if (_cache.has(id)) return _cache.get(id);
  let css = '';
  for (const k of keys) {
    const f = FACES[k];
    css += "@font-face{font-family:'" + f.family + "';font-weight:" + f.weight + ';font-style:' + f.style +
      ';src:url(data:font/woff;base64,' + f.b64 + ") format('woff');}";
  }
  const out = css ? '<style>' + css + '</style>' : '';
  _cache.set(id, out);
  return out;
}

// The face a browser would choose for this weight (the CSS font-matching rule), from the faces we have.
function _pickFace(family, weight, italic) {
  const all = FAMILY_FACES[family] || [];
  let pool = all.filter((k) => (FACES[k].style === 'italic') === italic);
  if (!pool.length) pool = all;
  if (!pool.length) return null;
  const ws = pool.map((k) => FACES[k].weight);
  const above = (lo, hi) => ws.filter((w) => w >= lo && w <= hi).sort((x, y) => x - y)[0];
  const below = (v) => ws.filter((w) => w < v).sort((x, y) => y - x)[0];
  let w;
  if (ws.includes(weight)) w = weight;
  else if (weight >= 400 && weight <= 500) w = above(weight, 500) ?? below(weight) ?? above(500, 1000);
  else if (weight < 400) w = below(weight) ?? above(weight, 1000);
  else w = above(weight, 1000) ?? below(weight);
  return pool.find((k) => FACES[k].weight === w) || pool[0];
}

/**
 * Returns the <style> block (or '') that makes the finished SVG text render in the embedded faces.
 * Only the faces a design really uses are embedded: each text element's family, weight and slant are read from the
 * SVG. Designs that contain the naira sign also get Inter for it where the chosen face lacks that glyph.
 */
export function fontFaceStyle(svg) {
  const text = String(svg || '');
  const needsNaira = text.indexOf('\u20A6') !== -1;
  const keys = new Set();
  const rx = /font-family="([^"]*)"\s+font-weight="(\d+)"([^>]*)>/g;
  let m;
  while ((m = rx.exec(text))) {
    const first = /'(Cg[A-Za-z]+)'/.exec(m[1]);
    if (!first || !FAMILY_FACES[first[1]]) continue;
    const weight = parseInt(m[2], 10);
    const italic = /font-style="italic"/.test(m[3]);
    const k = _pickFace(first[1], weight, italic);
    if (k) keys.add(k);
    if (needsNaira && FALLBACK[first[1]]) {
      const fb = _pickFace(FALLBACK[first[1]], weight, false);
      if (fb) keys.add(fb);
    }
  }
  return _css(Array.from(keys).sort());
}

export const EMBEDDED_FAMILIES = Object.keys(FAMILY_FACES);
